import { useState, type FormEvent } from 'react';
import { JxButton, JxInputField, JxSelect, JxSwitch, JxToast } from '@jinx-ui/react';

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель', meta: 'Только чтение' },
  { value: 'editor', label: 'Редактор', meta: 'Может править' },
  { value: 'admin', label: 'Администратор', meta: 'Полный доступ' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [invited, setInvited] = useState<string | null>(null);

  const isValid = EMAIL_PATTERN.test(email.trim());
  const errorText = touched && !isValid ? 'Введите адрес вида name@example.com' : undefined;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);
    if (!isValid) return;
    setInvited(email.trim());
    setEmail('');
    setTouched(false);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 12px)' }}>
      {invited ? (
        <JxToast
          variant="success"
          title="Приглашение отправлено"
          message={`Мы позвали ${invited} в команду.`}
          onClose={() => setInvited(null)}
        />
      ) : null}

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 12px)' }}>
        <JxInputField
          label="Электронная почта"
          type="email"
          name="email"
          required
          placeholder="name@example.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          onBlur={() => setTouched(true)}
          helperText="Приглашение придёт на этот адрес"
          errorText={errorText}
        />

        <JxSelect
          label="Роль в команде"
          placeholder="Выберите роль"
          options={ROLES}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление"
          name="notify"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <div style={{ display: 'flex', gap: 'var(--jx-gap, 8px)' }}>
          <JxButton type="submit" variant="primary" disabled={!isValid}>
            Отправить приглашение
          </JxButton>
        </div>
      </form>
    </div>
  );
}

